MATCH (:PlantItem {tag: 'E-26501'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'EJ-12304'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: "V-58901"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: "P-41202B"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: "EA-28201"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:AngleValve)
WHERE v.unit_id = '247'
RETURN count(v) AS number_of_angle_valves, collect(v.tag) AS tags;

MATCH (:PlantItem {tag: "M-37801"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (tank:Tank {tag: "TK-601"})-[:send_to]-(valve:PlantItem)<-[:control]-(:PlantItem)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (a:PlantItem {tag: "V-37901"}), (b:PlantItem {tag: "V-37801"})
RETURN a.tag AS tag_1, b.tag AS tag_2, a.unit_id AS unit_1, b.unit_id AS unit_2, a.unit_id = b.unit_id AS same_unit
}

MATCH (equipment:PlantItem {tag: "TK-43501"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem {tag: "V-25801"})-[:send_to*1..]->(downstream:PlantItem)-[:is_located_in]->(unit:PlantSection)
WHERE unit.unit_id <> v.unit_id
RETURN count(DISTINCT unit.unit_id) AS other_unit_count;

MATCH (v:PlantItem:SpringLoadedGlobeSafetyValve)
WHERE v.unit_id = '460'
RETURN count(v) AS valve_count, collect(v.tag) AS tags;

MATCH (e:PlantItem:Equipment {tag: "E-24301"})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment {tag: 'E-39501'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(instrument:ProcessInstrumentationFunction)
WHERE instrument.loop_tag = 'TIAH-118054'
RETURN DISTINCT equipment.tag AS tag;
